package net.civeira.phylax.feature.observe.observedfingerprintrule.domain;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedFingerprintRuleChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_fingerprint_rule_change_set_builder() {
    ObservedFingerprintRuleChangeSet one = new ObservedFingerprintRuleChangeSet().uid("one")
        .name("one").origin(ObservedSourceReference.of("one"))
        .field(ObservedFingerprintRuleFieldOptions.MESSAGE).pattern("one")
        .effect(ObservedFingerprintRuleEffectOptions.GROUP_AS).groupKey("one").enabled(true)
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getName().get(), "Value must equals to the intial value");
    one.name("two");
    Assertions.assertEquals("two", one.getName().get(), "Value must equals to the assigned value");
    one.unset("name");
    Assertions.assertFalse(one.getName().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSourceReference.of("one"), one.getOrigin().get(),
        "Value must equals to the intial value");
    one.origin(ObservedSourceReference.of("two"));
    Assertions.assertEquals(ObservedSourceReference.of("two"), one.getOrigin().get(),
        "Value must equals to the assigned value");
    one.unset("origin");
    Assertions.assertFalse(one.getOrigin().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedFingerprintRuleFieldOptions.MESSAGE, one.getField().get(),
        "Value must equals to the intial value");
    one.field(ObservedFingerprintRuleFieldOptions.TYPE);
    Assertions.assertEquals(ObservedFingerprintRuleFieldOptions.TYPE, one.getField().get(),
        "Value must equals to the assigned value");
    one.unset("field");
    Assertions.assertFalse(one.getField().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getPattern().get(), "Value must equals to the intial value");
    one.pattern("two");
    Assertions.assertEquals("two", one.getPattern().get(),
        "Value must equals to the assigned value");
    one.unset("pattern");
    Assertions.assertFalse(one.getPattern().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedFingerprintRuleEffectOptions.GROUP_AS, one.getEffect().get(),
        "Value must equals to the intial value");
    one.effect(ObservedFingerprintRuleEffectOptions.IGNORE_FRAME);
    Assertions.assertEquals(ObservedFingerprintRuleEffectOptions.IGNORE_FRAME,
        one.getEffect().get(), "Value must equals to the assigned value");
    one.unset("effect");
    Assertions.assertFalse(one.getEffect().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getGroupKey().get(),
        "Value must equals to the intial value");
    one.groupKey("two");
    Assertions.assertEquals("two", one.getGroupKey().get(),
        "Value must equals to the assigned value");
    one.unset("groupKey");
    Assertions.assertFalse(one.getGroupKey().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getEnabled().get(), "Value must equals to the intial value");
    one.enabled(false);
    Assertions.assertEquals(false, one.getEnabled().get(),
        "Value must equals to the assigned value");
    one.unset("enabled");
    Assertions.assertFalse(one.getEnabled().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
